test('relevance fields match the Python scorer',()=>{for(const [record,expected] of cases)expect([record,addAiRelevance(record)]).toEqual([record,expected]);});
const data:[string,boolean][]=[["DuckDB 2.0 and the lakehouse",true],["Spark of genius",false],["Apache Spark 4",true],["ETL",true],["PETL",false],["dbt-core",true],["Kafka on the shore",true]];
test('data engineering signal needs whole words',()=>{for(const [text,expected] of data)expect([text,hasDataSignal(text)]).toEqual([text,expected]);});

test('a model name followed by a version number is an AI signal', () => {
  expect(addAiRelevance({ site_id: 'hackernews', title: 'Phi-5 tops the leaderboard' }).ai_is_related).toBe(true);
});
